60		/**
61		 * Tope de BYTES serializados por petición. Por defecto 3 MiB.
62		 *
63		 * El tope por número de filas no basta: api-db-go corre sobre Fiber, cuyo
64		 * `BodyLimit` acota el cuerpo de la petición, y 500 mensajes ricos (embeds
65		 * llenos, 10 adjuntos) se van a ~18 MiB. El servidor contestaba 413, el
66		 * reintento fallaba igual y el lote ENTERO se descartaba — 500 mensajes
67		 * perdidos, en silencio salvo por un log de error.
68		 *
69		 * 3 MiB deja margen holgado bajo el límite del servidor para cabeceras y para
70		 * la diferencia entre esta estimación y el JSON final.
71		 */
72		maxBatchBytes?: number;
73		/**
74		 * Tope duro de filas en memoria. Si api-db está caído, sin este tope el
75		 * buffer crecería hasta agotar el heap del worker y tumbar el bot por un
76		 * fallo de un servicio auxiliar. Al llegar al tope se descartan las filas
77		 * NUEVAS y se cuentan en `droppedMessages`. Por defecto 20.000 filas
78		 * (~40 s de margen a 500 msg/s).
79		 */
80		maxBufferedMessages?: number;
81		/** Mismo tope para los ids pendientes de marcar como borrados. */
82		maxBufferedDeletes?: number;
83	}
84	
85	// `type` y no `interface` a propósito: los alias de tipo obtienen firma de
86	// índice implícita, así que un `MessageIngestStats` se puede pasar donde se
87	// espera `Record<string, unknown>` — que es exactamente lo que pide el `meta`
88	// del logger. Una interface no lo permitiría.
89	export type MessageIngestStats = {
90		/** Filas aceptadas por el buffer desde el arranque. */
91		enqueued: number;
92		/** Filas confirmadas por api-db. */
93		flushed: number;
94		/** Filas descartadas por tope de buffer o por fallo tras reintento. */
95		droppedMessages: number;
96		/** Ids de borrado descartados por tope de buffer o por fallo tras reintento. */
97		droppedDeletes: number;
98		/** Lotes que fallaron (incluye los que luego el reintento salvó). */
99		failedBatches: number;
100		/** Filas esperando ahora mismo. */
101		pendingMessages: number;
102		/** Ids de borrado esperando ahora mismo. */
103		pendingDeletes: number;
104		/** Filas que el servidor rechazó una a una sin tumbar su lote. */
105		rejectedMessages: number;
106		/** Filas descartadas aquí por no caber ellas solas en `maxBatchBytes`. */
107		oversizedMessages: number;
108	};
109	
110	const DEFAULTS = {
111		enabled: true,
112		flushIntervalMs: 500,
113		maxBatchSize: 500,
114		maxBatchBytes: 3 * 1024 * 1024,
115		maxBufferedMessages: 20_000,
116		maxBufferedDeletes: 20_000
117	} as const;
118	
119	export class MessageIngestBuffer {
120		private readonly transport: MessageIngestTransport;
121		private readonly logger: MessageIngestLogger;
122		private readonly options: Required<MessageIngestBufferOptions>;
123	
124		/** Map en vez de array: coalesce por id y conserva el orden de inserción. */
125		private readonly pending = new Map<string, MessageStoreWrite>();
126		private readonly pendingDeletes = new Set<string>();
127	
128		private timer: NodeJS.Timeout | null = null;
129		private flushing = false;
130		private stopped = false;
131	
132		private stats = {
133			enqueued: 0,
134			flushed: 0,
135			droppedMessages: 0,
136			droppedDeletes: 0,
137			failedBatches: 0,
138			rejectedMessages: 0,
139			oversizedMessages: 0
140		};
141	
142		constructor(
143			transport: MessageIngestTransport,
144			logger: MessageIngestLogger,
145			options: MessageIngestBufferOptions = {}
146		) {
147			this.transport = transport;
148			this.logger = logger;
149			this.options = { ...DEFAULTS, ...options };
150		}
151	
152		start(): void {
153			if (this.timer || !this.options.enabled) return;
154			this.stopped = false;
155			this.timer = setInterval(() => {
156				void this.flush();
157			}, this.options.flushIntervalMs);
158			// El intervalo no debe mantener vivo el event loop: si todo lo demás
159			// terminó, el proceso tiene que poder salir.
160			this.timer.unref?.();
161		}
162	
163		/**
164		 * Encola un mensaje. Nunca lanza ni espera: los handlers del gateway están
165		 * en la ruta caliente y no pueden bloquearse por el store.
166		 */
167		add(row: MessageStoreWrite): void {
168			if (!this.options.enabled || this.stopped) return;
169	
170			const existing = this.pending.get(row.id);
171			if (existing) {
172				// Fusión sobre lo pendiente en lugar de reemplazo: los payloads de
173				// MESSAGE_UPDATE son parciales por contrato, así que un reemplazo
174				// directo perdería campos que solo traía el MESSAGE_CREATE.
175				this.pending.set(row.id, mergeRow(existing, row));
176				return;
177			}
178	
179			if (this.pending.size >= this.options.maxBufferedMessages) {
180				this.stats.droppedMessages++;
181				return;
182			}
183	
184			this.pending.set(row.id, row);
185			this.stats.enqueued++;
186	
187			// Volcado anticipado por tamaño: sin esto, una ráfaga por encima de
188			// `maxBatchSize` esperaría igualmente al tick y el lote crecería sin
189			// control entre ticks.
190			if (this.pending.size >= this.options.maxBatchSize) void this.flush();
191		}
192	
193		/**
194		 * Devuelve la fila que sigue esperando en el buffer, si la hay.
