193				// —por un `catch` que responde después de un camino que ya respondió—
194				// desbalancearía el contador, y un contador que sólo sube acaba cerrando el
195				// módulo entero a base de falsos «demasiadas en vuelo».
196				let settled = false;
197				// Los argumentos se reenvían TAL CUAL, no uno a uno: pasarlos con nombre
198				// (`err, value, trailer, flags`) convertía una llamada de dos argumentos en
199				// una de cuatro con dos `undefined` inventados, y eso ya cambia lo que ve
200				// grpc-js — además de romper cualquier aserto sobre la forma de la respuesta.
201				const release = ((...args: Parameters<grpc.sendUnaryData<Res>>): void => {
202					if (!settled) {
203						settled = true;
204						this.releaseInFlight(normalizedModuleKey);
205					}
206					callback(...args);
207				}) as grpc.sendUnaryData<Res>;
208	
209				// Un handler que lance de forma SÍNCRONA no llegaría a su callback nunca, y
210				// el hueco se quedaría cogido para siempre.
211				try {
212					handler(call, release);
213				} catch (err) {
214					if (!settled) {
215						settled = true;
216						this.releaseInFlight(normalizedModuleKey);
217					}
218					throw err;
219				}
220			};
221		}
