		let removed = 0;
		for (const [key, state] of this.buckets) {
			const rule = key.startsWith("rpc:") ? this.rpcRules.get(key.split(":").slice(2).join(":")) : undefined;
			const windowMs = rule?.windowMs ?? this.moduleRule.windowMs;
			if (now - state.windowStart >= windowMs * 2) {
				this.buckets.delete(key);
