// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import type { MessageResponseIPC } from "@kena/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

/**
 * Auditoría 2026-08-11 (Q3/Q5) — `pendingRequests` sin `maxPending`.
 *
 * Sin techo, un worker más lento que el ritmo de entrada hace crecer el Map
 * sin límite — cada entrada retiene resolve/reject, un Timeout y el payload
 * completo en el cierre. Estos tests fijan el contrato del techo: por encima
 * de `maxPending`, `trackRequest` rechaza de inmediato en vez de encolar.
 */
describe("RequestTracker maxPending ceiling", () => {
	let tracker: RequestTracker;

	beforeEach(() => {
		vi.useFakeTimers();
		tracker = new RequestTracker(30000, 2);
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("rejects a new request immediately once the ceiling is reached", async () => {
		const first = tracker.trackRequest("trace-1");
		const second = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(2);

		const third = tracker.trackRequest("trace-3");
		await expect(third).rejects.toThrow(/queue full/i);

		// The rejected request never occupied a slot.
		expect(tracker.getPendingCount()).toBe(2);

		// The two requests that got in are unaffected.
		const response: MessageResponseIPC = {
			success: true,
			data: { ok: true },
			timestamp: new Date().toISOString(),
			request_id: "trace-1"
		} as any;
		tracker.resolveRequest("trace-1", response);
		await expect(first).resolves.toEqual(response);

		tracker.rejectRequest("trace-2", new Error("cancelled"));
		await expect(second).rejects.toThrow("cancelled");
	});

	it("accepts a new request again once a slot frees up", async () => {
		tracker.trackRequest("trace-1");
		const second = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(2);

		tracker.rejectRequest("trace-2", new Error("cancelled"));
		await expect(second).rejects.toThrow("cancelled");
		expect(tracker.getPendingCount()).toBe(1);

		const third = tracker.trackRequest("trace-3");
		expect(tracker.getPendingCount()).toBe(2);

		tracker.rejectRequest("trace-1", new Error("cancelled"));
		tracker.rejectRequest("trace-3", new Error("cancelled"));
		await expect(third).rejects.toThrow("cancelled");
	});
});

